export const YkAISuggestions=defineComponent({name:'YkAISuggestions',props:{items:{type:Array,default:()=>[]},disabled:Boolean,layout:{type:String,default:'chips'}},emits:['select'],setup(p,{emit}){return()=>h('div',{class:['yk-ai-suggestions','is-'+p.layout],role:'group','aria-label':'建议问题'},p.items.map(item=>h('button',{type:'button',key:item.value,disabled:p.disabled||item.disabled,onClick:()=>emit('select',item)},[h('strong',{},item.label),p.layout==='cards'&&item.content?h('small',{},item.content):null,h('span',{'aria-hidden':'true'},'↗')])));}});
